-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_PRODUCT_UW_RULE
--   anchor      : HUB_PRODUCT
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Active Sequence Number
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PRODUCT_BK__K0)) as HUB_PRODUCT_HK,
        coalesce(nullif(trim(ELIGIBILITY_PARAMETER),''),'') as ACTIVE_SEQUENCE_NUMBER,
        ELIGIBILITY_PARAMETER as TRIGGER_CONDITION,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_MULTISET_ATTRIBUTE_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_msa_pv') }}
    where HUB_PRODUCT_K0__EMIT
)), hashed as (select *,
        case when TRIGGER_CONDITION is not null
             then md5(upper(coalesce(TRIGGER_CONDITION::varchar,'')))
        end as SAT_PRODUCT_UW_RULE_HASHDIFF
    from feeders)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_UW_RULE_HASHDIFF is not null
  and ACTIVE_SEQUENCE_NUMBER is not null
